const item = $input.item.json;
const b = item.body || item;
const chat_id = (b.chat_id || item.chat_id) ? String(b.chat_id || item.chat_id).trim() : '';
const request_id = (b.request_id || item.request_id) ? String(b.request_id || item.request_id).trim() : '';
const decision = (b.decision || item.decision) ? String(b.decision || item.decision).trim().toLowerCase() : '';
const source = b.source || item.source || 'webhook';

return {
  json: {
    chat_id,
    request_id,
    decision,
    source
  }
};

return {
  json: {
    status: 'error',
    message: 'Parameter request_id atau decision tidak valid. Harus confirm atau cancel.'
  }
};

return {
  json: {
    status: 'unauthorized',
    message: '⛔ Otorisasi Ditolak: Anda tidak memiliki wewenang supervisor untuk menyetujui aksi ini.'
  }
};

const norm = $('Normalisasi Keputusan').first().json;
const affected = $input.item.json.affected_count || 0;

let message = '';
if (norm.decision === 'confirm') {
  message = `✅ **SentinelOps AI - Action Confirmed**\n\n${affected} operational action(s) successfully executed and committed to plant operational tables.\n\nThis decision has been permanently recorded in ide09.audit_log.`;
} else {
  message = `❌ **SentinelOps AI - Proposal Cancelled**\n\nAction proposal for Request ID ${norm.request_id} has been cancelled by supervisor.\n\nNo operational changes were committed. Cancellation recorded in ide09.audit_log.`;
}

return {
  json: {
    status: 'success',
    request_id: norm.request_id,
    decision: norm.decision,
    affected_count: affected,
    chat_id: norm.chat_id,
    message,
    source: norm.source
  }
};
